from lib import *
from t_realestate import re_state_var, STATE_HOOK

TEMPLATES = []
add = TEMPLATES.append

TX_5016 = when("Texas: notice of existing lien (Prop. Code §5.016)", """
**Texas.** If the property is residential and an existing recorded lien will remain after the sale, Texas Property Code §5.016 requires the seller to give the buyer, and each lienholder, a separate written notice in at least 12-point type. It must be given at least seven days before the earlier of signing a binding contract or conveying the property, and it must contain the statutory warning and loan details. If a contract was signed without the notice, the buyer may terminate it within seven days after receiving the notice. Exceptions exist, for example when the buyer obtains a title insurance policy, or the buyer has bought, sold or contracted for four or more properties in the previous 12 months. The parties confirm that they have determined whether §5.016 applies and, if it does, that the notice was given on: {{tx_notice_date}}. Seller: [[initial:seller]] Buyer: [[initial:buyer]]""", "state == 'TX'")

DOS_TEXT = """Most residential mortgages contain a "due-on-sale" clause. Federal law (the Garn-St Germain Act, 12 U.S.C. §1701j-3) generally allows the lender to enforce it and demand payment of the entire loan balance when the property, or an interest in it, is transferred without the lender's consent. Transfers to an unrelated buyer, including through a land trust where the buyer becomes a beneficiary, generally are not within the Act's exemptions. Leases longer than three years, or any lease with an option to purchase, are not exempt either."""

CF_SOURCES = [SRC["garn"], SRC["regz36"], SRC["regz43"], SRC["safe"], SRC["tx_5016"], SRC["firpta"], SRC["esign_exc"]]

CF_COMMON_WATCH = [
    "Due-on-sale: the existing lender may call the whole loan due when title transfers. Federal law (Garn-St Germain) generally lets it do so, and the transfer exemptions do not cover a sale to an unrelated investor. Have a written plan, and the money, to refinance or pay off the loan if that happens.",
    "Never misrepresent ownership, occupancy or who is paying to a lender or an insurer. That can be mortgage or insurance fraud.",
    "Foreclosure rescue and equity purchaser laws: if the seller is behind on payments or in foreclosure, many states impose strict contract language, cancellation rights and prohibitions on buyers. Examples include California Civil Code §1695 et seq., New York Real Property Law §265-a, Maryland, Illinois and Minnesota. Violations can void the deal and create criminal liability.",
    "Texas: Property Code §5.016 requires a separate seller notice to the buyer and each lienholder at least seven days before contracting or conveying when a lien stays on residential property, unless an exception applies.",
    "The seller should get independent legal advice. A buyer's attorney or title company does not represent the seller.",
]

# ------------------------------------------------------------------ Subject-to addendum
st_vars = [
    re_state_var(),
    V("addendum_date", "Date", "date", help="Date of this addendum."),
    V("buyer_name", "Buyer", "party", help="Buyer taking title."),
    V("seller_name", "Seller", "party", help="Seller(s) who are the borrowers on the existing loan."),
    V("property_address", "Property", "address", help="Property address."),
    V("contract_date", "Purchase contract date", "date", help="The purchase contract this addendum attaches to."),
    V("loan1_lender", "First loan: lender or servicer", "text", help="Current servicer name from the latest mortgage statement."),
    V("loan1_last4", "First loan: last 4 digits of loan number", "text", help="Only the last four digits. Share the full number only through a secure channel."),
    V("loan1_balance", "First loan: approximate principal balance", "money", help="From the latest statement or a payoff statement."),
    V("loan1_rate", "First loan: interest rate", "percent", help="Current note rate."),
    V("loan1_payment", "First loan: monthly payment (including escrow)", "money", help="Total monthly payment."),
    V("loan1_type", "First loan: type", "select", default="conventional", options=["conventional", "FHA", "VA", "USDA", "other"], help="VA loans can affect the seller's VA entitlement while the loan remains outstanding."),
    V("loan1_escrow", "First loan has an escrow account for taxes and insurance?", "bool", False, "true", help="Escrowed taxes and insurance."),
    V("has_loan2", "Is there a second loan or HELOC?", "bool", False, "false", help="Second mortgage, HELOC or other lien."),
    V("loan2_details", "Second loan details", "longtext", False, help="Lender, last 4 digits, balance, rate, payment."),
    V("arrears", "Past-due amount on existing loans at signing", "money", False, "0", help="Amount needed to bring loans current. 0 if current."),
    V("arrears_paid_by", "Past-due amount paid by", "select", False, "Buyer, at closing, as part of the price", ["Buyer, at closing, as part of the price", "Seller, before closing"], help="Who cures arrears."),
    V("escrow_balance", "Existing escrow account balance goes to", "select", default="Buyer, as part of the purchase price", options=["Buyer, as part of the purchase price", "Seller, credited at closing"], help="Who gets the existing escrow balance."),
    V("first_buyer_payment", "First payment the buyer makes", "date", help="Due date of the first loan payment the buyer is responsible for."),
    V("payment_method", "How the buyer pays the loan", "select", default="through a licensed third-party loan servicing company", options=["through a licensed third-party loan servicing company", "directly to the lender, with proof to seller"], help="A servicer gives both sides independent records."),
    V("servicer_name", "Servicing company", "text", False, help="If using a servicer."),
    V("proof_days", "Buyer sends proof of payment within (days of due date)", "number", default="5", help="Proof such as a confirmation or statement."),
    V("cure_days", "Buyer's cure period after notice (days)", "number", default="10", help="Days to fix a missed payment after seller's written notice."),
    V("acceleration_plan", "If the lender calls the loan due", "select", default="refinance, pay off or sell before the lender deadline", options=["refinance, pay off or sell before the lender deadline", "refinance, pay off or sell, or deed the property back to seller"], help="Buyer's plan if the due-on-sale clause is enforced."),
    V("insurance_plan", "Insurance", "select", default="buyer obtains a policy with the existing lender as mortgagee and seller as additional insured", options=["buyer obtains a policy with the existing lender as mortgagee and seller as additional insured", "existing policy is changed to cover buyer as owner, with seller added as additional insured"], help="Insurer must be told the truth about ownership and occupancy."),
    V("payoff_years", "Buyer intends to pay off or refinance within (years)", "number", False, "", help="Optional target. Leave blank if there is no commitment."),
    V("performance_security", "Secure buyer's payment promise with a recorded deed of trust or mortgage to seller?", "bool", False, "false", help="Gives seller a foreclosure remedy if buyer stops paying. Attorney-drafted and recorded per state law."),
    V("tx_notice_date", "Texas §5.016 notice date (or 'not required: reason')", "text", False, help="Texas only."),
]

add(T(
    id="subject-to-addendum", title="Subject-To Existing Financing Addendum", category="creative-finance",
    tags=["subject to", "subto", "existing mortgage", "creative finance", "addendum", "state-aware"],
    summary="An original addendum for buying a property subject to the seller's existing mortgage, with separately initialed acknowledgments by buyer and seller.",
    useWhen="Attach to a purchase contract when the buyer takes title while the seller's mortgage stays in place and the buyer makes the payments. Use with the Seller Acknowledgments and Disclosures.",
    watchOuts=CF_COMMON_WATCH + [
        "The seller stays legally liable on the loan. Late payments by the buyer hurt the seller's credit, and a foreclosure can lead to a deficiency claim against the seller where state law allows.",
        "Insurance is a common failure point. Make sure the property is properly insured for the actual owner and occupancy, the lender stays listed as mortgagee, and nobody misstates facts to the insurer.",
        "A limited power of attorney must follow your state's execution rules, often notarization, and should never authorize new borrowing in the seller's name.",
        "Escrow shortages, tax reassessments after sale and HOA transfer fees can raise the monthly payment. Budget for them.",
        "VA loans: the seller's VA entitlement generally stays tied up while the loan is outstanding unless a qualified veteran substitutes entitlement.",
    ],
    stateAware=True, disclaimer=CF_DISCLAIMER,
    roles=[("buyer", "Buyer"), ("seller", "Seller")],
    variables=st_vars,
    sections=[
        S("What this addendum does", "This addendum, dated {{addendum_date}}, is part of the purchase contract dated {{contract_date}} between {{buyer_name}} (\"Buyer\") and {{seller_name}} (\"Seller\") for {{property_address}}, {{state}} (the \"Property\"). If it conflicts with the purchase contract, this addendum controls.\n\n**In plain terms:** Seller will deed the Property to Buyer. Seller's existing mortgage will stay in Seller's name and will not be paid off at closing. Buyer will make the mortgage payments from now on. The lender has not agreed to this and may have the right to demand full payment."),
        S("Existing loans", "The Property is subject to these loans (the \"Existing Loans\"):\n\n- **First loan:** {{loan1_lender}}, loan ending in {{loan1_last4}}, approximate balance {{loan1_balance}}, rate {{loan1_rate}}%, monthly payment {{loan1_payment}} ({{loan1_type}})."),
        opt("Loan escrow account", "The first loan has an escrow account for property taxes and insurance. The monthly payment includes escrow and can change after each annual escrow analysis, for example because of a tax reassessment after the sale or a new insurance premium. Buyer pays any escrow shortage or increased payment. Buyer: [[initial:buyer]]", "loan1_escrow"),
        opt("Second loan", "- **Second loan:** {{loan2_details}}", "has_loan2"),
        S("Purchase subject to the Existing Loans", "Buyer takes title subject to the Existing Loans. Buyer does not assume them, and the lender has not released Seller. The approximate balances are credited toward the purchase price as stated in the purchase contract. The actual balances may differ from the estimates. Buyer has received copies of the most recent loan statements. Buyer: [[initial:buyer]]"),
        S("Seller acknowledgments", "Seller understands and agrees, initialing each statement:\n\n" + "\n".join([
            ack("seller", "The Existing Loans stay in my name. I remain legally responsible to the lender until they are paid off or the lender releases me in writing."),
            ack("seller", "I will no longer own the Property, but loan payments, late payments, defaults and any foreclosure will continue to be reported on my credit."),
            ack("seller", "The lender may call the loan due because of this sale (see the Due-on-sale section). If Buyer cannot pay it off, the Property could be foreclosed and my credit harmed."),
            ack("seller", "The Existing Loans will continue to count as my debt, which may affect my ability to get new credit, including a mortgage on another home."),
            ack("seller", "I will keep receiving tax forms for the loan, such as Form 1098 mortgage interest statements, and I should get tax advice about this sale and who may deduct mortgage interest."),
            ack("seller", "I was advised to have my own attorney review this transaction, and I had the opportunity to do so."),
        ])),
        S("Buyer acknowledgments", "Buyer understands and agrees, initialing each statement:\n\n" + "\n".join([
            ack("buyer", "I will make every payment on the Existing Loans in full and on time, starting with the payment due {{first_buyer_payment}}, until they are paid off or refinanced."),
            ack("buyer", "The lender may call the loan due. I am responsible for paying it off, refinancing or otherwise resolving it under the plan below, and I have, or have a realistic way to obtain, the money to do that."),
            ack("buyer", "Payment amounts can change, for example because of escrow shortages, tax reassessment after the sale, insurance increases or an adjustable rate. I am responsible for the full amount due."),
            ack("buyer", "I will not represent myself to the lender or any insurer as the borrower, or misstate who owns or occupies the Property."),
        ])),
        S("Due-on-sale", DOS_TEXT + "\n\nNeither party has made any promise that the lender will not call the loan due. Buyer: [[initial:buyer]] Seller: [[initial:seller]]"),
        when("If the lender calls the loan: refinance, pay off or sell", "If the lender demands payment in full, Buyer will, at Buyer's sole expense and before the lender's deadline (or any extension the lender grants), refinance or pay off the Existing Loans, sell the Property and pay them off, or negotiate an assumption or other resolution the lender accepts in writing that releases or protects Seller. Buyer will keep making regular payments in the meantime, if the lender accepts them.", "acceleration_plan == 'refinance, pay off or sell before the lender deadline'"),
        when("If the lender calls the loan: refinance, pay off, sell or deed back", "If the lender demands payment in full, Buyer will, at Buyer's sole expense and before the lender's deadline (or any extension the lender grants), refinance or pay off the Existing Loans, sell the Property and pay them off, or negotiate an assumption or other resolution the lender accepts in writing. If Buyer cannot do any of these at least 30 days before the lender's deadline, Buyer will, at Seller's written election, convey the Property back to Seller by deed free of any liens or encumbrances Buyer created, with the loans current. Buyer will not be entitled to a refund of amounts paid. **The parties understand that a court may review a deed-back for fairness, and that state law may require a different process.** Buyer: [[initial:buyer]] Seller: [[initial:seller]]", "acceleration_plan == 'refinance, pay off or sell, or deed the property back to seller'"),
        S("Payments and proof", "Buyer will make payments {{payment_method}}. Servicing company (if any): {{servicer_name}}. Within {{proof_days}} days after each due date, Buyer will give Seller proof that the payment was made, or Seller will have access to the servicer's payment records. Seller may contact the lender at any time to confirm loan status."),
        S("Missed payments", "If a payment is not made by its due date (including the lender's grace period), Seller may give Buyer written notice. If Buyer does not make the payment, with any late fees, within {{cure_days}} days after notice, Buyer is in default. Seller may then make the payment, and Buyer will repay Seller within 10 days with interest at the highest lawful rate or 10% per year, whichever is lower. Seller may also pursue any other remedy the law and this agreement allow. Buyer's obligations under this addendum survive closing."),
        opt("Security for Buyer's promises", "To secure Buyer's obligation to keep the Existing Loans current and to repay any amounts Seller advances, Buyer will sign at closing a deed of trust or mortgage on the Property in favor of Seller, junior to the Existing Loans, drafted by an attorney to comply with the law of {{state}} and recorded in the county records. On a default, Seller may foreclose it as that law permits.", "performance_security"),
        S("Past-due amounts and escrow", "Past-due amounts on the Existing Loans at signing: {{arrears}}, to be paid by {{arrears_paid_by}}, so the loans are current at closing. The existing loan escrow account balance goes to {{escrow_balance}}. Any later escrow refund from the lender that belongs to Buyer will be paid to Buyer by Seller within 10 days after Seller receives it."),
        S("Insurance", "Insurance plan: {{insurance_plan}}. From closing, Buyer will keep the Property insured for its full replacement cost (plus flood insurance if the lender requires it), with the existing lender named as mortgagee as the loan documents require. Seller will be added as an additional insured or additional interest where the insurer allows. Each party will give the insurer accurate information about ownership and occupancy. Buyer will give Seller proof of coverage at closing and at each renewal. If the lender force-places insurance, Buyer will pay its cost and promptly obtain compliant coverage."),
        S("Authorization and limited power of attorney", "At closing Seller will sign:\n\n- a **third-party authorization** letting the lender and servicer talk with Buyer and the servicing company about the Existing Loans; and\n- a separate **limited power of attorney**, signed with the formalities the law of {{state}} requires (usually notarization), authorizing Buyer only to:\n  - request loan balances, payoff statements, payment histories and escrow analyses;\n  - make payments and set up online payment access, while Seller keeps the right to view the account;\n  - communicate with the hazard and flood insurers about the Property;\n  - deal with utilities, the owners' association and taxing authorities about the Property; and\n  - sign documents needed to pay off or refinance the Existing Loans in full, with the payoff going to the lender.\n\n**The power of attorney will not allow Buyer to borrow money, open credit, modify or extend the Existing Loans, or sign any other document in Seller's name.** It ends when the Existing Loans are paid off. Seller may revoke it for Buyer's uncured default. Seller: [[initial:seller]]"),
        S("Title, taxes and association", "Seller will convey title by the deed specified in the purchase contract, and the deed will be recorded. Buyer will obtain an owner's title insurance policy if available. From closing, Buyer pays property taxes, association dues, utilities and maintenance, whether or not escrowed. Seller will give Buyer copies of loan, tax, insurance and association notices Seller receives, within 5 days."),
        S("Payoff target", "Buyer intends to pay off or refinance the Existing Loans within {{payoff_years}} years, if a target is stated. Buyer will in any case pay them off when Buyer sells or transfers the Property. Buyer will not further encumber the Property in a way that impairs the Existing Loans."),
        TX_5016,
        S("Seller in default or foreclosure", "If the Existing Loans were in default, or any foreclosure notice had been issued, when the parties first discussed this transaction, the parties confirm they have checked whether the foreclosure-rescue or equity-purchaser law of {{state}} applies, and have complied with any required contract language, notices and cancellation rights. Buyer: [[initial:buyer]] Seller: [[initial:seller]]"),
        STATE_HOOK,
        S("Independent advice", "Each party has had the opportunity to consult its own attorney and tax adviser, and is not relying on the other party for legal, tax or financial advice. The closing agent does not represent Seller or Buyer unless separately engaged."),
        signatures([("buyer", "Buyer", "{{buyer_name}}"), ("seller", "Seller", "{{seller_name}}")]),
    ],
    sources=CF_SOURCES + [SRC["tx_wrap_sum"], src("California Civil Code §1695 (Home Equity Sales Contracts Act)", "https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=1695"), src("New York Real Property Law §265-a (distressed property consultants and equity purchasers)", "https://www.nysenate.gov/legislation/laws/RPP/265-A")],
))

# ------------------------------------------------------------------ Seller acknowledgments and disclosures
add(T(
    id="seller-acknowledgments-disclosures", title="Seller Acknowledgments and Disclosures (Creative Finance)", category="creative-finance",
    tags=["seller acknowledgment", "disclosure", "subject to", "seller finance", "consumer protection", "state-aware"],
    summary="Seller confirms, item by item, that they understand the deal, the equity involved, the risks, and that they were advised to get independent counsel.",
    useWhen="Any creative-finance purchase (subject-to, seller financing, wrap, lease-option, contract for deed) from a homeowner, especially an individual or older seller.",
    watchOuts=CF_COMMON_WATCH + [
        "An acknowledgment form does not cure unfair or deceptive conduct. Courts look at the whole transaction, including price, the seller's circumstances and how the deal was presented.",
        "If the seller is elderly, ill or under stress, slow down: encourage a trusted family member or attorney to be involved, and consider a cooling-off period even if not required.",
        "Use the seller's preferred language. Some states require contracts to be provided in the language in which they were negotiated, for example Texas for executory contracts and California for some contracts negotiated in Spanish, Chinese, Tagalog, Vietnamese or Korean.",
    ],
    stateAware=True, disclaimer=CF_DISCLAIMER,
    roles=[("seller", "Seller"), ("buyer", "Buyer")],
    variables=[
        re_state_var(),
        V("ack_date", "Date", "date", help="Date signed."),
        V("seller_name", "Seller", "party", help="Each owner should sign."),
        V("buyer_name", "Buyer", "party", help="Buyer or buying entity."),
        V("property_address", "Property", "address", help="Property address."),
        V("structure", "Transaction type", "select", default="subject to existing financing", options=["subject to existing financing", "seller financing", "wraparound financing", "lease with option to purchase", "contract for deed", "cash sale below market"], help="Main structure."),
        V("price", "Purchase price", "money", help="Total price."),
        V("cash_to_seller", "Cash the seller receives at closing", "money", help="Net cash to seller."),
        V("value_basis", "Seller's estimate of market value", "money", help="Seller's own estimate, from an appraisal, broker opinion or online estimate."),
        V("value_source", "Source of the value estimate", "text", default="Seller's own estimate", help="Where the estimate came from."),
        V("foreclosure_status", "Loan status", "select", default="current", options=["current", "behind on payments, no foreclosure notice", "foreclosure notice received or sale scheduled", "no mortgage"], help="Status of the seller's loans when discussions began."),
        V("cancel_days", "Seller's cooling-off period (business days)", "number", default="3", help="Time the seller has to cancel without penalty. Some states require a specific period, for example 5 business days under California's equity purchaser law."),
        V("language", "Language the deal was negotiated in", "text", default="English", help="Provide documents in this language where required."),
    ],
    sections=[
        S("Transaction", "Seller: {{seller_name}}. Buyer: {{buyer_name}}. Property: {{property_address}}, {{state}}. Type: {{structure}}. Purchase price: {{price}}. Cash Seller receives at closing: {{cash_to_seller}}. These acknowledgments are part of the purchase contract and its addenda. Negotiated in: {{language}}."),
        S("Capacity and voluntariness", "\n".join([
            ack("seller", "I am at least 18 years old, of sound mind, and not under the influence of anything that affects my judgment today."),
            ack("seller", "I am signing voluntarily. No one has threatened me, pressured me, or rushed me to sign."),
            ack("seller", "Every person who owns the Property, and any spouse whose signature the law requires, is signing these documents."),
            ack("seller", "I read and understand English or the language these documents are written in, or a translator I chose explained them to me."),
        ])),
        S("Price, value and equity", "\n".join([
            ack("seller", "I estimate the Property's market value at {{value_basis}} ({{value_source}}). I understand the price and cash I receive may be less than I could get by selling on the open market with an agent, after time, repairs and costs."),
            ack("seller", "I understand Buyer is an investor who intends to make a profit, for example by renting, reselling or refinancing the Property, and that Buyer may earn more from the Property than I do."),
            ack("seller", "I understand how much equity (value minus what I owe) I am giving up or receiving in this transaction."),
            ack("seller", "I was told I could get an appraisal, list the Property with a licensed agent, or seek other offers before signing."),
        ])),
        S("Alternatives and advice", "\n".join([
            ack("seller", "I was advised to talk with my own attorney, and a tax adviser, before signing, and I had the chance to do so. Buyer is not my attorney, agent or adviser."),
            ack("seller", "I know that alternatives may exist, such as a loan modification, forbearance, refinancing, a traditional sale, a short sale, or bankruptcy, and that free HUD-approved housing counselors can explain options."),
            ack("seller", "Buyer has not promised me anything that is not written in the signed documents."),
        ])),
        S("Structure-specific risks", "\n".join([
            ack("seller", "If my mortgage stays in place, I remain liable on it, it stays on my credit, and the lender may call it due because of the sale."),
            ack("seller", "If I am financing the sale, I may not receive all my money for years, Buyer could default, and I may have to foreclose or go to court to recover the Property."),
            ack("seller", "I understand when I give up possession, what happens to my personal property, and when I must move out."),
        ])),
        when("Foreclosure or default protections", "**Seller was behind on payments or facing foreclosure when talks began.** Many states have foreclosure-rescue or equity-purchaser laws that require specific contract language, notices and cancellation rights, and that prohibit certain terms such as lease-backs with options to repurchase. The parties confirm they have checked the law of {{state}} and that all required notices and contract terms have been provided and complied with. Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "foreclosure_status == 'foreclosure notice received or sale scheduled'"),
        when("Behind on payments", "Seller is behind on payments. Some state laws apply before a formal foreclosure notice is issued. The parties confirm they have checked the law of {{state}}. Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "foreclosure_status == 'behind on payments, no foreclosure notice'"),
        S("Cooling-off period", "Seller may cancel this transaction without penalty by written notice delivered to Buyer by midnight of the {{cancel_days}}th business day after Seller signs, or any longer period required by law. If Seller cancels, Buyer will return any documents Seller signed, and Seller will return any money received from Buyer. Seller: [[initial:seller]]"),
        S("Buyer's confirmation", "Buyer confirms that Buyer explained the transaction honestly, did not tell Seller it is the only option, encouraged Seller to seek independent advice, and has made no promises outside the written documents. Buyer: [[initial:buyer]]"),
        STATE_HOOK,
        signatures([("seller", "Seller", "{{seller_name}}"), ("buyer", "Buyer", "{{buyer_name}}", True)], "Signed on {{ack_date}}:"),
    ],
    sources=[src("California Civil Code §1695 (Home Equity Sales Contracts Act)", "https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=CIV&sectionNum=1695"), src("New York Real Property Law §265-a", "https://www.nysenate.gov/legislation/laws/RPP/265-A"), src("HUD: Find a housing counselor", "https://www.hud.gov/findacounselor"), src("CFPB: Help for homeowners facing foreclosure", "https://www.consumerfinance.gov/housing/"), SRC["garn"], SRC["tx_exec"]],
))

# ------------------------------------------------------------------ Seller financing addendum
SF_COMPLIANCE = V("compliance_path", "Federal lending-law path", "select", True, "one-property seller-financer exclusion", [
    "one-property seller-financer exclusion", "three-property seller-financer exclusion", "loan originated by a licensed mortgage loan originator", "business-purpose loan (not consumer credit)"],
    "Reg Z 12 CFR 1026.36(a)(4)-(5) excludes some seller financers from loan-originator rules if conditions are met. State SAFE Act and licensing laws may still apply. Verify with an attorney.")

add(T(
    id="seller-financing-addendum", title="Seller Financing Addendum", category="creative-finance",
    tags=["seller financing", "owner financing", "carryback", "promissory note", "deed of trust", "state-aware"],
    summary="Add owner financing terms to a purchase contract: down payment, rate, amortization, balloon, security, insurance and compliance.",
    useWhen="The seller will carry back a note for part of the purchase price, secured by a mortgage or deed of trust on the property.",
    watchOuts=[
        "Federal law: seller financing of a consumer's home can make the seller a 'loan originator' and a creditor subject to ability-to-repay rules. Regulation Z excludes a natural person, estate or trust financing one property in 12 months (no negative amortization, fixed rate or limited adjustable rate), and a person financing up to three properties (fully amortizing, good-faith ability-to-repay determination, so no balloon). Outside those exclusions, use a licensed mortgage loan originator.",
        "State law: many states have their own SAFE Act licensing and lending rules for seller financing (for example Texas Finance Code ch. 156/157/180 and ch. 159 for wraps). Verify locally.",
        "If the seller still has a mortgage on the property, this is really a wraparound. Use the wraparound addendum, because the existing lender's due-on-sale clause applies.",
        "The security instrument (mortgage or deed of trust) is state-specific, must be drafted for the property's state, signed with notarization and recorded. This addendum does not create a lien by itself.",
        "Balloon payments are a common cause of buyer default. Make sure the buyer has a realistic plan to refinance.",
        "Use a third-party loan servicer for payment records, escrow, Form 1098 reporting and year-end statements.",
    ],
    stateAware=True, disclaimer=CF_DISCLAIMER,
    roles=[("buyer", "Buyer (borrower)"), ("seller", "Seller (lender)")],
    variables=[
        re_state_var(),
        V("addendum_date", "Date", "date", help="Date of addendum."),
        V("buyer_name", "Buyer", "party", help="Borrower."),
        V("seller_name", "Seller", "party", help="Lender."),
        V("property_address", "Property", "address", help="Property address."),
        V("contract_date", "Purchase contract date", "date", help="Contract this attaches to."),
        V("price", "Purchase price", "money", help="Total price."),
        V("down_payment", "Down payment", "money", help="Cash at closing, including earnest money."),
        V("financed_amount", "Amount financed by seller", "money", help="Note principal."),
        V("rate", "Interest rate", "percent", help="Annual rate. Check usury limits."),
        V("rate_type", "Rate type", "select", default="fixed", options=["fixed", "adjustable after 5 or more years"], help="The Reg Z exclusions require a fixed rate or one that adjusts only after 5+ years with reasonable caps."),
        V("amortization_years", "Amortization (years)", "number", default="30", help="Schedule used to calculate the payment."),
        V("payment", "Monthly principal and interest", "money", help="Calculated payment."),
        V("first_payment", "First payment date", "date", help="First due date."),
        V("balloon", "Balloon payment?", "bool", False, "false", help="Entire balance due before the loan fully amortizes. Not allowed under the three-property exclusion."),
        V("balloon_months", "Balloon due after (months)", "number", False, "60", help="When the balance is due."),
        V("escrow", "Buyer pays monthly escrow for taxes and insurance?", "bool", False, "true", help="Recommended."),
        V("late_fee", "Late fee", "text", default="5% of the payment if more than 15 days late", help="Within state limits."),
        V("lien_position", "Lien position", "select", default="first lien", options=["first lien", "second lien behind a new buyer loan"], help="Seller's priority."),
        V("security_instrument", "Security instrument", "select", default="deed of trust", options=["deed of trust", "mortgage", "security deed", "the instrument customary in the state of the property"], help="Depends on state."),
        SF_COMPLIANCE,
        V("credit_review", "Buyer provides credit report, income and asset documentation?", "bool", False, "true", help="Supports a good-faith ability-to-repay determination."),
        V("servicer", "Loan servicing company", "text", False, "", help="Third-party servicer."),
        V("due_on_sale_in_note", "Include a due-on-sale clause in the seller's note?", "bool", False, "true", help="Seller can call the note due if buyer transfers the property."),
    ],
    sections=[
        S("Addendum", "This addendum, dated {{addendum_date}}, is part of the purchase contract dated {{contract_date}} between {{buyer_name}} (\"Buyer\") and {{seller_name}} (\"Seller\") for {{property_address}}, {{state}}. If it conflicts with the purchase contract, this addendum controls."),
        S("Financing terms", "- Purchase price: {{price}}\n- Down payment: {{down_payment}}\n- Amount financed by Seller: {{financed_amount}}\n- Interest rate: {{rate}}% per year ({{rate_type}})\n- Amortization: {{amortization_years}} years\n- Monthly principal and interest: {{payment}}, first due {{first_payment}}\n- Late charge: {{late_fee}}\n- Prepayment: allowed at any time without penalty"),
        opt("Balloon payment", "**The entire unpaid balance is due {{balloon_months}} months after the first payment date.** Buyer understands that the regular payments will not pay off the loan by then, and that Buyer will need to refinance, sell or otherwise pay the balance. Seller has no obligation to extend or refinance. Buyer: [[initial:buyer]]", "balloon"),
        S("Note and security", "At closing Buyer will sign a promissory note for the amount financed, and a {{security_instrument}} securing it as a {{lien_position}} on the Property. Both will be prepared by an attorney or title professional licensed in {{state}}, in the form customary there. The security instrument will be notarized and recorded in the county records at closing. Seller may obtain a lender's title insurance policy at Seller's expense, unless the purchase contract says otherwise."),
        opt("Due-on-sale in Seller's note", "The note and security instrument will allow Seller to require payment in full if Buyer sells or transfers the Property or an interest in it without Seller's written consent, except transfers that federal law protects.", "due_on_sale_in_note"),
        opt("Escrow for taxes and insurance", "Buyer will pay one-twelfth of the estimated annual property taxes and insurance premiums with each monthly payment, into an escrow account held by the servicer, which will pay those bills when due and provide an annual escrow statement.", "escrow"),
        S("Insurance and maintenance", "Buyer will keep the Property insured for full replacement cost, with Seller named as mortgagee or loss payee, keep it in good repair, pay taxes and assessments before they are delinquent, and not commit waste. If Buyer fails to, Seller may pay and add the cost to the loan balance."),
        opt("Buyer's credit and ability to repay", "Within 5 days after the Effective Date of the purchase contract, Buyer will give Seller a current credit report, proof of income (pay stubs, tax returns or bank statements), and a list of debts. Seller will make a good-faith determination that Buyer can reasonably repay the loan. Seller may terminate the purchase contract within 5 days after receiving the documents if Seller reasonably determines Buyer cannot repay, and Buyer receives the earnest money back. Buyer authorizes Seller to obtain Buyer's credit report for this purpose. Buyer: [[initial:buyer]]", "credit_review"),
        S("Lending-law compliance", "The parties intend this loan to comply with federal and state lending law using this path: **{{compliance_path}}**. Each party has had the opportunity to consult an attorney about Regulation Z (including 12 CFR 1026.36(a)(4)-(5) and 1026.43), the SAFE Act and the licensing and disclosure laws of {{state}}. If a licensed mortgage loan originator is required, Seller will engage one and the loan terms will be adjusted as needed to comply. Seller: [[initial:seller]] Buyer: [[initial:buyer]]"),
        S("Servicing", "Payments will be made to {{servicer}} (if named), which will keep payment records, provide year-end interest statements, and handle escrow. Servicing fees are paid as the parties agree in writing."),
        S("Existing liens", "Seller confirms there is no existing mortgage or lien on the Property that will remain after closing. If there is, the parties will instead use a wraparound addendum, because the existing lender's rights are affected. Seller: [[initial:seller]]"),
        S("Default", "Default, notice, cure and foreclosure will follow the note, the security instrument and the law of {{state}}. Seller will give Buyer at least 30 days' written notice and opportunity to cure a payment default before accelerating, or longer if the law requires."),
        STATE_HOOK,
        signatures([("buyer", "Buyer", "{{buyer_name}}"), ("seller", "Seller", "{{seller_name}}")]),
    ],
    sources=[SRC["regz36"], SRC["regz43"], SRC["safe"], SRC["tx_wrap_sum"], SRC["garn"]],
))

# ------------------------------------------------------------------ Secured promissory note
add(T(
    id="secured-promissory-note", title="Promissory Note Secured by Real Estate", category="creative-finance",
    tags=["promissory note", "secured note", "seller financing", "real estate", "balloon"],
    summary="The buyer's note for a seller-financed sale, secured by a separately recorded mortgage or deed of trust.",
    useWhen="Use with the Seller Financing Addendum. The note is signed by the borrower only. The security instrument must be drafted for the property's state and recorded.",
    watchOuts=[
        "This note does not create a lien by itself. The mortgage or deed of trust that secures it must be drafted for the state, signed, notarized and recorded.",
        "E-signatures: E-SIGN excludes UCC Article 3 negotiable instruments, except that notes secured by real property can be 'transferable records' only if a system that establishes control is used. If the note may be sold or pledged, sign a wet-ink original.",
        "Dodd-Frank/Reg Z and state lending and usury laws can limit balloon payments, prepayment penalties, late fees and rates for consumer loans. See the Seller Financing Addendum.",
        "Keep the original note in a safe place. Lost notes create problems in foreclosure.",
    ],
    stateAware=True, disclaimer=CF_DISCLAIMER,
    roles=[("borrower", "Borrower")],
    variables=[
        re_state_var(),
        V("note_date", "Date", "date", help="Closing date."),
        V("borrower_name", "Borrower", "party", help="Buyer."),
        V("borrower_address", "Borrower address", "address", help="For notices."),
        V("lender_name", "Lender (note holder)", "party", help="Seller."),
        V("lender_address", "Lender address", "address", help="For notices and payments."),
        V("property_address", "Property securing the note", "address", help="Property address."),
        V("principal", "Principal", "money", help="Amount financed."),
        V("rate", "Interest rate", "percent", help="Annual fixed rate."),
        V("payment", "Monthly payment", "money", help="Principal and interest."),
        V("first_payment", "First payment date", "date", help="First due date."),
        V("maturity", "Maturity date", "date", help="Final due date, or the balloon date."),
        V("balloon", "Balloon note?", "bool", False, "false", help="Large final payment."),
        V("late_days", "Grace period (days)", "number", default="15", help="Days before a late charge."),
        V("late_percent", "Late charge (% of payment)", "percent", default="5", help="Within state limits."),
        V("security_instrument", "Security instrument", "select", default="deed of trust", options=["deed of trust", "mortgage", "security deed"], help="Securing this note."),
        V("pay_to", "Payments made to", "text", default="the Lender at the address above, or a servicer the Lender designates in writing", help="Where to pay."),
    ],
    sections=[
        S("Promise to pay", "On {{note_date}}, for value received, {{borrower_name}} (\"Borrower\") promises to pay to the order of {{lender_name}} (\"Lender\") the principal sum of {{principal}}, with interest on the unpaid principal at {{rate}}% per year from the date of this note until paid."),
        S("Payments", "Borrower will pay {{payment}} per month, starting {{first_payment}} and on the same day of each month after that, until {{maturity}}, when all unpaid principal and interest is due. Payments are made to {{pay_to}}, and are applied to late charges, then interest, then principal."),
        opt("Balloon payment notice", "**THIS IS A BALLOON NOTE. THE MONTHLY PAYMENTS WILL NOT PAY OFF THE LOAN BY THE MATURITY DATE. THE ENTIRE REMAINING BALANCE WILL BE DUE ON {{maturity}}. LENDER HAS NO OBLIGATION TO REFINANCE OR EXTEND IT.** Borrower: [[initial:borrower]]", "balloon"),
        S("Prepayment", "Borrower may prepay all or part of the principal at any time without penalty. Partial prepayments do not change the due date or amount of later monthly payments unless Lender agrees in writing."),
        S("Late charge", "If a payment is not received within {{late_days}} days after it is due, Borrower will pay a late charge of {{late_percent}}% of the overdue payment, but not more than the law allows."),
        S("Security", "This note is secured by a {{security_instrument}} of the same date on the property at {{property_address}}, {{state}}, which describes when Lender may require immediate payment of the full balance, including on transfer of the property where the law allows."),
        S("Default", "If Borrower does not pay any amount when due, or breaks a promise in the security instrument, and does not cure within 30 days after Lender's written notice (or any longer period the law requires), Lender may declare the entire unpaid balance immediately due and enforce the security instrument as the law of {{state}} permits. Borrower will pay Lender's reasonable costs of collection and attorney fees, to the extent the law allows."),
        S("Other terms", "Interest will never exceed the maximum lawful rate. Any excess is applied to principal. Borrower waives presentment, demand, protest and notice of dishonor, to the extent the law allows. Notices go to the addresses above: Borrower at {{borrower_address}}, Lender at {{lender_address}}. This note is governed by the law of {{state}}. Each person who signs is fully responsible for the whole debt."),
        signatures([("borrower", "Borrower", "{{borrower_name}}")], "Borrower signs this note. (Only the borrower signs a note. The lender keeps the signed original.)"),
    ],
    sources=[SRC["esign_exc"], src("E-SIGN transferable records, 15 U.S.C. §7021 (Cornell LII)", "https://www.law.cornell.edu/uscode/text/15/7021"), SRC["ucc3"], SRC["regz36"], SRC["regz43"]],
))

# ------------------------------------------------------------------ Wraparound addendum
add(T(
    id="wraparound-addendum", title="Wraparound Financing Addendum (AITD)", category="creative-finance",
    tags=["wraparound", "wrap", "aitd", "all-inclusive trust deed", "seller financing", "state-aware"],
    summary="Seller finances the sale with a new note that 'wraps' the seller's existing mortgage, which the seller keeps paying from the buyer's payments.",
    useWhen="The seller has an existing loan that will stay in place, and the seller will carry a new note for the buyer that includes the existing balance.",
    watchOuts=CF_COMMON_WATCH + [
        "Buyer risk: the buyer depends on the seller to keep paying the underlying loan. Use a third-party servicer that pays the underlying lender first, and give the buyer the right to pay the underlying lender directly if the seller doesn't.",
        "Texas: wrap mortgage loans on residential property are regulated by Finance Code ch. 159. Unless exempt, the wrap lender must be licensed or registered and give the buyer a disclosure statement at least seven days before closing. Buyers get rescission and offset rights, and the seller holds payments in trust. Property Code §5.016 notice also applies.",
        "All lending-law issues from the Seller Financing Addendum (Regulation Z exclusions, SAFE Act, state licensing) also apply to wraps.",
        "Insurance must protect the underlying lender, the seller and the buyer. A loss payout must go first to repairs or the underlying loan.",
    ],
    stateAware=True, disclaimer=CF_DISCLAIMER,
    roles=[("buyer", "Buyer (wrap borrower)"), ("seller", "Seller (wrap lender)")],
    variables=[
        re_state_var(),
        V("addendum_date", "Date", "date", help="Date."),
        V("buyer_name", "Buyer", "party", help="Wrap borrower."),
        V("seller_name", "Seller", "party", help="Wrap lender."),
        V("property_address", "Property", "address", help="Property address."),
        V("contract_date", "Purchase contract date", "date", help="Contract this attaches to."),
        V("underlying", "Underlying loan(s)", "longtext", help="Lender, last 4 digits of the loan number, balance, rate, monthly payment and maturity for each loan that stays in place."),
        V("price", "Purchase price", "money", help="Total price."),
        V("down_payment", "Down payment", "money", help="Cash at closing."),
        V("wrap_amount", "Wrap note principal", "money", help="Price minus down payment. Includes the underlying balance."),
        V("wrap_rate", "Wrap interest rate", "percent", help="Annual rate on the wrap note."),
        V("wrap_payment", "Wrap monthly payment", "money", help="Buyer's payment, which must be at least the underlying payments."),
        V("wrap_term_months", "Wrap term (months)", "number", default="360", help="Term."),
        V("balloon_months", "Balloon due after (months, blank if none)", "number", False, "", help="If a balloon applies."),
        V("servicer", "Third-party servicer", "text", help="Licensed servicer that collects buyer's payment and pays the underlying lender."),
        V("escrow", "Taxes and insurance", "select", default="escrowed by the servicer", options=["escrowed by the servicer", "escrowed in the underlying loan", "paid directly by buyer with proof to seller"], help="How taxes and insurance are paid."),
        SF_COMPLIANCE,
        V("tx_notice_date", "Texas §5.016 notice date (or 'not required: reason')", "text", False, help="Texas only."),
        V("tx_159_status", "Texas Finance Code ch. 159 status", "select", False, "seller is exempt (verify)", ["seller is exempt (verify)", "seller is licensed or registered and the ch. 159 disclosure was delivered at least 7 days before closing"], help="Texas only."),
    ],
    sections=[
        S("Addendum", "This addendum, dated {{addendum_date}}, is part of the purchase contract dated {{contract_date}} between {{buyer_name}} (\"Buyer\") and {{seller_name}} (\"Seller\") for {{property_address}}, {{state}}."),
        S("Underlying loans", "The Property is and will remain subject to these loans, which stay in Seller's name (the \"Underlying Loans\"):\n\n{{underlying}}"),
        S("Wrap note", "The purchase price is {{price}}. Buyer pays a down payment of {{down_payment}} at closing, and will sign a wraparound promissory note to Seller for the balance of {{wrap_amount}}, at {{wrap_rate}}% per year, payable at {{wrap_payment}} per month for {{wrap_term_months}} months (balloon after {{balloon_months}} months, if stated). It will be secured by a wraparound mortgage or deed of trust on the Property, junior to the Underlying Loans, drafted for {{state}}, notarized and recorded. The wrap note includes the Underlying Loan balances. Buyer is not assuming the Underlying Loans."),
        S("Payment flow", "Buyer will pay {{servicer}} (the \"Servicer\"), not Seller directly. Each month the Servicer will first pay the Underlying Loan payments (and escrow, if applicable), then remit the balance to Seller. Seller instructs the Servicer that this order of payment cannot be changed without Buyer's written consent. Taxes and insurance: {{escrow}}. Both parties will have access to the Servicer's records."),
        S("Seller's obligations on the Underlying Loans", "Seller will keep the Underlying Loans current using the funds the Servicer receives, will not modify, extend, refinance or further borrow against the Underlying Loans or the Property, and will forward to Buyer within 5 days any notice from the underlying lenders. Seller's duty to pay the Underlying Loans from Buyer's payments is a trust obligation for Buyer's benefit."),
        S("Buyer's protection", "If an Underlying Loan becomes delinquent for any reason other than Buyer's failure to pay the wrap note, Buyer may pay the underlying lender directly to cure it, and deduct those payments, plus costs, from amounts due on the wrap note. Seller: [[initial:seller]]"),
        S("Payoff", "When Buyer pays off the wrap note, including by refinancing or selling, the payoff will first pay off the Underlying Loans in full, and Seller will deliver a release of the wraparound security instrument. Seller will cooperate in providing payoff statements."),
        S("Due-on-sale", DOS_TEXT + "\n\nIf an underlying lender calls its loan due, the parties will cooperate in good faith to refinance or pay it off. Unless they agree otherwise in writing, Buyer will refinance the wrap note within the lender's deadline, and the payoff will retire the Underlying Loans. Buyer: [[initial:buyer]] Seller: [[initial:seller]]"),
        S("Insurance", "Buyer will keep the Property insured for full replacement cost, naming the underlying lenders and Seller as mortgagees or loss payees in order of priority. Insurance proceeds will be used for repairs or to pay down the loans in order of priority."),
        S("Lending-law compliance", "Federal lending-law path: **{{compliance_path}}**. The parties have had the opportunity to consult counsel about Regulation Z, the SAFE Act and the law of {{state}} on wraparound loans. Seller: [[initial:seller]] Buyer: [[initial:buyer]]"),
        when("Texas: Finance Code ch. 159 (wrap mortgage loans)", "**Texas.** Texas Finance Code chapter 159 regulates wrap mortgage loans on residential property. Unless exempt, the wrap lender must be licensed or registered and must give the buyer a separate written disclosure (including an insurance disclosure) at least seven days before the loan agreement is entered into. The buyer may rescind within seven days after receiving it, or later if it was not given on time. The wrap lender holds the buyer's payments in trust and must use them to pay the underlying debt, taxes and insurance. The buyer may also deduct amounts paid to cure the lender's defaults. Status: {{tx_159_status}}. Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "state == 'TX'"),
        TX_5016,
        STATE_HOOK,
        signatures([("buyer", "Buyer", "{{buyer_name}}"), ("seller", "Seller", "{{seller_name}}")]),
    ],
    sources=CF_SOURCES + [SRC["tx_wrap"], SRC["tx_wrap_sum"]],
))

# ------------------------------------------------------------------ Novation
add(T(
    id="novation-agreement", title="Novation Agreement", category="creative-finance",
    tags=["novation", "substitution", "assignment", "contract transfer", "three-party"],
    summary="Replace one party to a contract with a new party, with the other party's consent, releasing the departing party.",
    useWhen="All three parties agree that a new party steps into a contract (for example a purchase contract, lease, service contract or loan) in place of an original party, who is released. Unlike an assignment, a novation releases the original party.",
    watchOuts=[
        "A novation needs the consent of the remaining party. Without that, it is only an assignment and the original party stays liable.",
        "Real estate investors sometimes use 'novation' to describe deals where the investor renovates or lists the seller's property and keeps the difference. Selling or marketing someone else's property for compensation without a license can be unlicensed brokerage, and may also fall under wholesaling disclosure laws. Get local legal advice before using a novation that way.",
        "A mortgage lender must agree before a new borrower can replace the existing one. Without the lender's written release, the original borrower stays liable.",
        "Check the original contract for anti-assignment clauses, consent requirements and required forms.",
    ],
    disclaimer=CF_DISCLAIMER,
    roles=[("original", "Departing party"), ("newparty", "New party"), ("remaining", "Remaining party")],
    variables=[
        V("novation_date", "Effective date", "date", help="When the substitution takes effect."),
        V("original_name", "Departing party", "party", help="Party being replaced."),
        V("new_name", "New party", "party", help="Party stepping in."),
        V("remaining_name", "Remaining party", "party", help="Other party to the contract, who consents."),
        V("contract_desc", "Contract", "text", help="Title, date and parties of the original contract."),
        V("contract_subject", "Subject matter", "text", False, "", help="E.g. the property address or services."),
        V("consideration", "Payment to departing party (if any)", "text", False, "None", help="Any payment for stepping out."),
        V("past_obligations", "Who is responsible for obligations before the effective date", "select", default="departing party", options=["departing party", "new party"], help="Past performance and liabilities."),
        V("deposit_transfer", "Deposits or funds held under the contract", "text", False, "Remain held and are credited to the new party.", help="Earnest money, security deposits, retainers."),
        state_var(),
    ],
    sections=[
        S("Parties and contract", "Departing party: {{original_name}}. New party: {{new_name}}. Remaining party: {{remaining_name}}.\n\nContract: {{contract_desc}} (the \"Contract\"), concerning {{contract_subject}}."),
        S("Substitution", "Effective {{novation_date}}, the New party replaces the Departing party as a party to the Contract. The New party accepts all of the Departing party's rights, and agrees to perform all of its obligations arising on or after the effective date, as if it had originally signed the Contract."),
        S("Release", "The Remaining party releases the Departing party from all obligations under the Contract arising on or after the effective date, and agrees to look only to the New party for them. Responsibility for obligations arising before the effective date: {{past_obligations}}."),
        S("Consent", "The Remaining party consents to this novation and confirms that the Contract is in effect and, to its knowledge, no party is in default. Remaining party: [[initial:remaining]]"),
        S("Payment and deposits", "Payment to the Departing party: {{consideration}}. Deposits and funds held under the Contract: {{deposit_transfer}}"),
        S("Contract otherwise unchanged", "Except for the substitution of parties, the Contract is unchanged and remains in effect."),
        S("Real estate use", "If the Contract concerns real estate, each party confirms it has considered whether any licensing, wholesaling disclosure, or lender consent requirement applies, and that this novation is not being used to market or sell another person's property for compensation in violation of real estate licensing law. Departing party: [[initial:original]] New party: [[initial:newparty]]"),
        general_terms(),
        signatures([("original", "Departing party", "{{original_name}}", True), ("newparty", "New party", "{{new_name}}", True), ("remaining", "Remaining party", "{{remaining_name}}", True)]),
    ],
    sources=[SRC["wholesale_tracker"], SRC["il_454"], SRC["garn"], src("Cornell LII Wex: Novation", "https://www.law.cornell.edu/wex/novation")],
))

# ------------------------------------------------------------------ Lease-option
add(T(
    id="lease-option-agreement", title="Residential Lease with Option to Purchase", category="creative-finance",
    tags=["lease option", "rent to own", "option to purchase", "lease purchase", "state-aware"],
    summary="A residential lease paired with a separate, paid option giving the tenant the right (not the obligation) to buy at a set price.",
    useWhen="An owner rents a home to a tenant who wants the chance to buy it later, with an option fee and possibly rent credits.",
    watchOuts=[
        "Texas: a residential lease combined with an option to purchase is treated as an executory contract if the term is more than 180 days. Texas Property Code ch. 5, subch. D then requires disclosures, recording within 30 days, annual accounting statements, specific default notices and more, with penalties. Many investors keep Texas lease-options to 180 days or less. Get Texas counsel.",
        "Other states may treat a lease-option, especially with large option fees and rent credits, as an equitable mortgage or installment sale that requires foreclosure rather than eviction. Some, such as Illinois and Minnesota, regulate rent-to-own arrangements.",
        "Due-on-sale: Garn-St Germain exempts leases of three years or less only if they contain no option to purchase. A lease-option on mortgaged property can let the lender call the loan.",
        "Record a memorandum of option so the tenant-buyer's rights are protected against later liens and buyers.",
        "Tenant-buyers should verify the owner is current on the mortgage, taxes and HOA dues, and that title is clean, before paying a large option fee.",
        "Landlord-tenant law still governs the lease part, including deposits, habitability, notices and eviction. The option fee is not a security deposit.",
    ],
    stateAware=True, disclaimer=CF_DISCLAIMER,
    roles=[("owner", "Owner (landlord and optionor)"), ("tenant", "Tenant (optionee)")],
    variables=[
        re_state_var(),
        V("agreement_date", "Date", "date", help="Date signed."),
        V("owner_name", "Owner", "party", help="Landlord and optionor."),
        V("owner_address", "Owner address", "address", help="For notices."),
        V("tenant_name", "Tenant", "party", help="Tenant and optionee."),
        V("tenant_email", "Tenant email", "email", help="For notices."),
        V("property_address", "Property", "address", help="Property address."),
        V("legal_description", "Legal description", "longtext", help="For the memorandum of option."),
        V("lease_start", "Lease start", "date", help="Start."),
        V("lease_end", "Lease end", "date", help="End. In Texas, more than 180 days triggers the executory contract statute."),
        V("rent", "Monthly rent", "money", help="Market rent."),
        V("deposit", "Security deposit", "money", help="Separate from the option fee, within state limits."),
        V("option_fee", "Option fee", "money", help="Non-refundable payment for the option, credited at closing if exercised."),
        V("option_price", "Purchase price if exercised", "money", help="Fixed price, or attach a formula."),
        V("rent_credit", "Rent credit toward price per on-time payment", "money", False, "0", help="Portion of each on-time rent payment credited at closing. Large credits increase the risk the deal is treated as a sale."),
        V("option_expires", "Option expires", "date", help="Last day to exercise. Usually the lease end date."),
        V("closing_days", "Close within (days after exercise)", "number", default="60", help="Time to obtain financing and close."),
        V("tenant_repairs", "Tenant pays minor repairs up to", "money", False, "250", help="Per repair. Owner remains responsible for habitability and major systems."),
        V("record_memo", "Record a memorandum of option?", "bool", False, "true", help="Protects the tenant's option."),
        V("owner_has_mortgage", "Is the property mortgaged?", "bool", False, "true", help="Owner keeps the mortgage current."),
    ],
    sections=[
        S("Parties and property", "Owner: {{owner_name}}, {{owner_address}}. Tenant: {{tenant_name}} ({{tenant_email}}). Property: {{property_address}}, {{state}}, legally described as {{legal_description}} (the \"Property\")."),
        S("Two separate agreements", "This document contains (A) a residential lease and (B) an option to purchase. They are separate agreements with separate consideration. Tenant is not obligated to buy. Until Tenant exercises the option and closes, Owner owns the Property and Tenant is a tenant."),
        S("Part A — Lease: term and rent", "The lease runs from {{lease_start}} to {{lease_end}}. Rent is {{rent}} per month, due on the 1st. Security deposit: {{deposit}}, held and returned as required by the law of {{state}}. Landlord-tenant law of {{state}} applies to the lease, including notice, habitability and eviction rules."),
        S("Part A — Lease: maintenance", "Owner will keep the Property habitable and maintain the roof, structure, and major systems (plumbing, electrical, heating and cooling) unless damage is caused by Tenant. Tenant will keep the Property clean, handle routine upkeep and lawn care, and pay for minor repairs up to {{tenant_repairs}} each. Tenant may not make structural changes without Owner's written consent. Other lease terms are those of the parties' standard residential lease, attached, which controls lease matters not covered here."),
        S("Part B — Option: grant and fee", "In exchange for a non-refundable option fee of {{option_fee}}, paid at signing, Owner grants Tenant the exclusive option to buy the Property for {{option_price}}. The option may be exercised at any time until {{option_expires}} by written notice to Owner. The option fee is not rent and not a security deposit. If Tenant buys, it is credited toward the price. If Tenant does not exercise the option, Owner keeps it. Tenant: [[initial:tenant]]"),
        S("Part B — Option: rent credits", "For each monthly rent payment received on time and in full, {{rent_credit}} will be credited toward the price at closing. Rent credits have no cash value and are not refundable if the option is not exercised. Tenant: [[initial:tenant]]"),
        S("Part B — Option: exercise and closing", "After Tenant exercises the option, the parties will close within {{closing_days}} days, using a purchase agreement on customary terms for {{state}} consistent with this option. Tenant is responsible for obtaining financing. Owner will deliver marketable title by warranty deed, free of monetary liens, at closing. If Tenant cannot close on time, the option ends unless the parties agree in writing to extend it."),
        S("Part B — Option: effect of lease default", "If Tenant is in material default under the lease, for example unpaid rent not cured after the legally required notice, Owner may give written notice that the option will end if the default is not cured within 30 days. The option is personal to Tenant and may not be assigned without Owner's written consent."),
        S("Owner's promises during the option", "Owner will not sell, further mortgage or encumber the Property in a way that prevents conveying clear title at the option price, will pay taxes, insurance and any mortgage on time, and will give Tenant written notice within 5 days of receiving any default, foreclosure, tax or lien notice. Owner: [[initial:owner]]"),
        opt("Existing mortgage", DOS_TEXT + " Owner confirms the mortgage is current and will keep it current. If the lender accelerates the loan, Owner remains responsible for it, and Tenant may, but need not, exercise the option early. Owner: [[initial:owner]] Tenant: [[initial:tenant]]", "owner_has_mortgage"),
        opt("Memorandum of option", "The parties will sign a short memorandum of this option, notarized, which Tenant may record in the county records. When the option expires or ends unexercised, Tenant will sign a release of the memorandum on request.", "record_memo"),
        when("Texas: executory contract warning", "**Texas.** If this lease and option, taken together, last more than 180 days, Texas Property Code ch. 5, subch. D treats them as an executory contract for conveyance. That requires, among other things, pre-signing disclosures (including a survey or plat, tax certificates and insurance information), a contract in the language of negotiation, recording within 30 days, an annual accounting statement each January, a specific default notice with statutory cure periods, conversion rights and limits on liens. Penalties apply for non-compliance. The parties have consulted Texas counsel. Owner: [[initial:owner]] Tenant: [[initial:tenant]]", "state == 'TX'"),
        S("Disclosures", "Owner has delivered the seller disclosures that would be required in a sale of the Property in {{state}}, and the federal lead-based paint disclosure if the home was built before 1978. Tenant had the opportunity to inspect the Property before signing. Tenant: [[initial:tenant]]"),
        STATE_HOOK,
        general_terms(gov="state"),
        signatures([("owner", "Owner", "{{owner_name}}"), ("tenant", "Tenant", "{{tenant_name}}")], "Signed on {{agreement_date}}:"),
    ],
    sources=[SRC["tx_exec"], SRC["garn"], SRC["il_67"], SRC["lead_cfr"], SRC["esign_exc"]],
))

# ------------------------------------------------------------------ Contract for deed
add(T(
    id="contract-for-deed", title="Contract for Deed (Installment Land Contract)", category="creative-finance",
    tags=["contract for deed", "land contract", "installment sale", "bond for deed", "executory contract", "state-aware"],
    summary="Seller keeps title while the buyer pays the price in installments, then delivers the deed at payoff. Includes strong state-specific protections.",
    useWhen="Only after both sides have local legal advice. Contracts for deed are heavily regulated in many states and have a history of abuse. A conventional sale with seller financing and a recorded mortgage is often safer for both sides.",
    watchOuts=[
        "Strongly regulated in many states. Examples: Texas (Prop. Code ch. 5, subch. D: disclosures, recording within 30 days, annual statements, cure periods, foreclosure after 40% or 48 payments), Ohio (ORC ch. 5313: required terms, recording within 20 days, foreclosure after five years or 20% paid), Illinois (765 ILCS 67: 3-day attorney general disclosure, recording within 10 business days, 90-day cure), North Carolina (G.S. ch. 47H: required terms, 3-business-day cancellation right, 30-day cure), Minnesota (§559.21 termination; 2024 amendments), Arizona (§33-741 et seq. forfeiture rules), Washington (RCW 61.30) and Iowa (ch. 656).",
        "Many courts treat a contract for deed like a mortgage. The seller may have to foreclose rather than simply evict, especially after the buyer has built up equity.",
        "If the seller has a mortgage, a contract for deed can trigger the due-on-sale clause, and the buyer can lose everything if the seller's lender forecloses. Texas generally restricts executory contracts on property with liens.",
        "Buyers usually take on repairs, taxes and insurance without owning the property. Habitability, code and lead-paint rules may still bind the seller.",
        "The federal lending laws for seller financing (Regulation Z, SAFE Act) can apply to contracts for deed too.",
    ],
    stateAware=True, disclaimer=CF_DISCLAIMER + " Contracts for deed are among the most heavily regulated and litigated real estate arrangements. Do not use this template without an attorney licensed in the property's state.",
    roles=[("seller", "Seller (vendor)"), ("buyer", "Buyer (vendee)")],
    variables=[
        re_state_var(),
        V("contract_date", "Date", "date", help="Date signed."),
        V("seller_name", "Seller", "party", help="Owner who keeps title."),
        V("seller_address", "Seller address", "address", help="For notices and payments."),
        V("buyer_name", "Buyer", "party", help="Buyer."),
        V("buyer_address", "Buyer address", "address", help="For notices."),
        V("property_address", "Property", "address", help="Street address."),
        V("legal_description", "Legal description", "longtext", help="From the deed."),
        V("price", "Purchase price", "money", help="Total price."),
        V("fees", "Other charges included in the contract", "money", False, "0", help="Some states require these to be stated separately."),
        V("down_payment", "Down payment", "money", help="Paid at signing."),
        V("balance", "Principal balance", "money", help="Price plus included charges, minus the down payment."),
        V("rate", "Interest rate", "percent", help="Annual rate, within usury limits."),
        V("payment", "Monthly payment", "money", help="Principal and interest."),
        V("number_payments", "Number of payments", "number", help="Total installments."),
        V("first_payment", "First payment date", "date", help="First due date."),
        V("balloon", "Balloon payment?", "bool", False, "false", help="Balance due before full amortization."),
        V("balloon_date", "Balloon due date", "date", False, help="When the remaining balance is due."),
        V("escrow", "Taxes and insurance paid through escrow?", "bool", False, "true", help="Monthly escrow."),
        V("liens", "Existing liens on the property", "longtext", default="None", help="List every mortgage or lien, with the lender and balance."),
        V("public_orders", "Pending government orders or code violations", "longtext", default="None known", help="Many states require disclosure."),
        V("record_days", "Seller records the contract within (days)", "number", default="10", help="Use the shortest deadline in your state: Illinois 10 business days, Ohio 20 days, Texas 30 days."),
        V("cure_days", "Buyer's cure period after default notice (days)", "number", default="60", help="Never less than the state minimum. Illinois requires 90 days, Texas 30 or 60, North Carolina 30."),
        V("cancel_days", "Buyer's right to cancel (business days)", "number", default="3", help="North Carolina and Illinois require at least 3 business days."),
    ],
    sections=[
        S("Parties and property", "Seller: {{seller_name}}, {{seller_address}}. Buyer: {{buyer_name}}, {{buyer_address}}. Date: {{contract_date}}.\n\nSeller agrees to sell and Buyer agrees to buy {{property_address}}, {{state}}, legally described as:\n\n{{legal_description}}\n\n(the \"Property\"). Seller keeps legal title as security until Buyer pays the price in full. Then Seller will deliver a deed."),
        S("Price and payments", "- Purchase price: {{price}}\n- Other charges included: {{fees}}\n- Down payment: {{down_payment}}\n- Principal balance: {{balance}}\n- Interest: {{rate}}% per year, simple interest on the unpaid balance\n- Payments: {{number_payments}} monthly payments of {{payment}}, starting {{first_payment}}\n- Prepayment: Buyer may prepay all or part at any time without penalty\n- Late charge: no more than 5% of the late payment, and only if more than 15 days late, unless the law of {{state}} sets a lower limit\n\nAn amortization schedule is attached. Buyer: [[initial:buyer]]"),
        opt("Balloon payment", "**The entire remaining balance is due on {{balloon_date}}. Regular payments will not pay off the contract by then. Seller has no obligation to extend it.** Buyer: [[initial:buyer]]", "balloon"),
        S("Existing liens and public orders", "Existing liens on the Property: {{liens}}\n\nPending government orders or code violations: {{public_orders}}\n\nSeller will keep every existing lien current, will not place any new mortgage or lien on the Property, and will not let the total of liens exceed the balance Buyer owes. If Seller fails to pay an existing lien, Buyer may pay it directly and deduct the payment from what Buyer owes Seller. Seller will give Buyer copies of any default, foreclosure or tax notice within 5 days. Seller: [[initial:seller]]"),
        S("Taxes, insurance and repairs", "From the date of this contract, Buyer is responsible for property taxes and assessments, homeowner's insurance naming both parties as their interests appear, utilities and routine repairs, unless this contract says otherwise. Seller remains responsible for any condition Seller knew about and did not disclose, and for compliance with laws that place obligations on Seller. Insurance proceeds for damage will be used to repair the Property unless both parties agree otherwise in writing."),
        opt("Escrow", "Buyer will pay one-twelfth of the estimated annual taxes and insurance with each payment, into an escrow account held by a third-party servicer, which will pay those bills and provide annual escrow statements.", "escrow"),
        S("Recording", "Seller will record this contract, or a memorandum of it if the law of {{state}} allows, signed and notarized by both parties, in the county records within {{record_days}} days after signing, and give Buyer a recorded copy. Seller pays the recording fee. Buyer may record it if Seller does not."),
        S("Annual statement", "Each January, Seller will give Buyer a written statement showing payments received, principal and interest paid, the remaining balance and number of payments, and taxes and insurance paid for the prior year."),
        S("Default, cure and remedies", "If Buyer fails to pay or perform, Seller must give Buyer written notice, delivered as the law of {{state}} requires, stating the default and the amount needed to cure. Buyer has {{cure_days}} days after the notice, or any longer period the law requires, to cure. Seller may then use only the remedies the law of {{state}} allows, which may require judicial foreclosure rather than forfeiture or eviction, especially once Buyer has paid a substantial part of the price. Buyer: [[initial:buyer]]"),
        S("Deed at payoff", "Within 30 days after Buyer pays in full, Seller will deliver a general warranty deed (or the best deed Seller can lawfully give, if the parties agree in writing) conveying title free of all liens except those Buyer agreed to, and will pay to release any Seller liens."),
        S("Buyer's right to cancel", "**Buyer may cancel this contract at any time until midnight of the {{cancel_days}}th business day after signing or receiving a signed copy, whichever is later, by written notice to Seller. If Buyer cancels, Seller will refund all payments within 10 days.** Buyer: [[initial:buyer]]"),
        S("Disclosures", "Seller has given Buyer all seller disclosures required by the law of {{state}}, the federal lead-based paint disclosure if the home was built before 1978, any disclosure statement the law requires for contracts for deed, and copies of the most recent tax bill and insurance policy. Buyer had the opportunity to obtain an inspection, appraisal and title search before signing. Buyer: [[initial:buyer]]"),
        when("Texas: executory contract requirements", "**Texas.** Texas Property Code ch. 5, subch. D applies to residential executory contracts longer than 180 days. Among other things: required disclosures before signing (survey or plat, tax certificates, insurance, financing terms); the contract must be in the language of negotiation; recording within 30 days; annual accounting each January; a specific default notice; a 30-day cure period, or 60 days in some cases (for example once 40% of the price or 48 monthly payments have been paid), after which Seller's remedy in those cases is limited to selling the property through a trustee's sale; limits on late fees; a deed within 30 days after final payment; and restrictions on liens. Penalties and Deceptive Trade Practices Act remedies apply. Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "state == 'TX'"),
        when("Ohio: land installment contract requirements", "**Ohio.** Ohio Revised Code ch. 5313 requires specific contract terms (including a provision letting Buyer pay Seller's defaulted mortgage and receive credit), signing in duplicate with the formalities of a deed, recording within 20 days and delivery to the county auditor, review of a metes-and-bounds description by the county engineer, and specific default procedures. After the contract has been in effect for five years, or Buyer has paid 20% or more of the price, Seller must foreclose rather than forfeit. Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "state == 'OH'"),
        when("Illinois: Installment Sales Contract Act", "**Illinois.** The Installment Sales Contract Act (765 ILCS 67) applies to sellers who enter into more than three such contracts in 12 months for residential property. It requires the Attorney General's disclosure and a 3-business-day review period, 28 specified contract terms, recording within 10 business days, a 90-day cure period, and seller repair duties unless shifted in compliance with the Act, among other things. Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "state == 'IL'"),
        when("North Carolina: contracts for deed", "**North Carolina.** N.C. Gen. Stat. ch. 47H requires a written, acknowledged contract with specified terms, a completed residential property disclosure statement, a 14-point bold notice of the buyer's 3-business-day cancellation right above the buyer's signature, recording, and a default notice with a 30-day cure period before forfeiture. Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "state == 'NC'"),
        when("Minnesota: contracts for deed", "**Minnesota.** Termination is governed by Minn. Stat. §559.21, which 2024 amendments changed for residential property, including barring termination where the vendor failed to record as required by §507.235. Additional rules apply to investor sellers. Consult Minnesota counsel. Seller: [[initial:seller]] Buyer: [[initial:buyer]]", "state == 'MN'"),
        STATE_HOOK,
        general_terms(gov="state"),
        signatures([("seller", "Seller", "{{seller_name}}"), ("buyer", "Buyer", "{{buyer_name}}")], "**Buyer: read the right-to-cancel section above before signing.** Both parties sign this contract, and must also sign it before a notary for recording."),
    ],
    sources=[SRC["tx_exec"], SRC["oh_5313"], SRC["il_67"], SRC["nc_47h"], SRC["mn_559"], SRC["az_33742"], SRC["wa_6130"], SRC["ia_656"], SRC["garn"], SRC["regz36"], SRC["lead_cfr"]],
))

# ------------------------------------------------------------------ Real estate JV
add(T(
    id="real-estate-joint-venture", title="Real Estate Joint Venture Agreement", category="creative-finance",
    tags=["real estate jv", "joint venture", "fix and flip", "capital partner", "operating partner", "buy and hold"],
    summary="A capital partner and an operating partner team up on one property: who funds, who works, how profits are split, and how it ends.",
    useWhen="One party brings the money (or credit) and the other finds, renovates, manages or sells a specific property.",
    watchOuts=[
        "Passive money partners: if one party contributes only money and relies on the other's efforts, the arrangement may be a security (an investment contract) under federal and state law. Many sponsors use an LLC and exemptions with counsel.",
        "Put title in an entity, or record the JV's interest. A partner holding title alone can sell or mortgage the property without the other's knowledge.",
        "Renovation work may require a contractor's license. Selling the property for the JV may require a real estate license if a partner is paid a commission.",
        "Define the budget, overrun funding and the sale or refinance trigger. Most JV disputes come from cost overruns and disagreements about when to sell.",
        "Tax: an unincorporated JV is usually a partnership for tax purposes (Form 1065). Flips may be taxed as ordinary income.",
    ],
    disclaimer=CF_DISCLAIMER,
    roles=[("capital", "Capital partner"), ("operator", "Operating partner")],
    variables=[V("effective_date", "Effective date", "date", help="Start date.")]
    + party_vars("capital", "Capital partner") + party_vars("operator", "Operating partner") + [
        V("property_address", "Property", "address", help="Target property."),
        V("strategy", "Strategy", "select", default="renovate and sell", options=["renovate and sell", "renovate, rent and refinance", "buy and hold rental", "wholesale or assign"], help="Business plan."),
        V("title_holder", "Title held by", "select", default="a new LLC owned by both partners", options=["a new LLC owned by both partners", "the capital partner, with a recorded memorandum of this agreement", "the operating partner, with a recorded memorandum of this agreement"], help="An LLC is usually safest."),
        V("capital_amount", "Capital partner contributes", "money", help="Total committed funds for purchase and renovation."),
        V("operator_contribution", "Operating partner contributes", "longtext", default="Finding the property, managing the renovation, contractor oversight, marketing and sale.", help="Services, cash or both."),
        V("budget", "Budget", "longtext", help="Purchase price, closing costs, renovation budget, holding costs, contingency."),
        V("overrun_plan", "Cost overruns are funded by", "select", default="capital partner as additional capital that is repaid before profits", options=["capital partner as additional capital that is repaid before profits", "both partners in proportion to profit shares", "operating partner"], help="Who pays overruns."),
        V("pref_return", "Preferred return to capital partner (annual %)", "percent", False, "0", help="Paid before profits are split. 0 for none."),
        V("split_capital", "Capital partner's share of profits", "percent", default="50", help="After return of capital and any preferred return."),
        V("split_operator", "Operating partner's share of profits", "percent", default="50", help="After return of capital and any preferred return."),
        V("timeline", "Target timeline", "text", default="Purchase within 30 days, renovation within 120 days, sale within 9 months", help="Milestones."),
        V("spend_limit", "Operator may spend without approval up to", "money", default="2500", help="Per item, within the budget."),
        V("exit_trigger", "If not sold or refinanced by", "date", help="Deadline after which the capital partner may require a sale."),
        state_var(),
    ],
    sections=[
        S("Partners and property", party_line("capital", "Capital partner") + "\n\n" + party_line("operator", "Operating partner") + "\n\nThe partners form a joint venture for the property at {{property_address}} (the \"Property\"). Strategy: {{strategy}}. Effective {{effective_date}}."),
        S("Title", "The Property will be held by {{title_holder}}. Neither partner may sell, mortgage or lease the Property except as this agreement allows."),
        S("Contributions", "Capital partner will contribute up to {{capital_amount}}, deposited in the venture's bank account as needed under the budget. Operating partner will contribute: {{operator_contribution}}\n\nBudget:\n\n{{budget}}\n\nCost overruns will be funded by {{overrun_plan}}."),
        S("Management", "Operating partner manages the day-to-day project, hires licensed and insured contractors, obtains permits, and keeps Capital partner informed with weekly updates and photos. Operating partner may spend up to {{spend_limit}} per item within the budget. These need both partners' written approval: changes to the budget or scope over 10%, any loan or lien, the listing price and any sale or lease, any contract with a partner's affiliate, and any decision outside the strategy."),
        S("Money and records", "All venture money goes through a separate bank account in the venture's name, with both partners having online access. Each partner may inspect the books at any time. Operating partner will provide a final accounting within 30 days after the sale or refinance."),
        S("Distributions", "Net proceeds from sale, refinance or operations will be distributed in this order:\n1. Repay venture debts and costs of sale.\n2. Return each partner's cash capital contributions, including overrun capital.\n3. Pay Capital partner a preferred return of {{pref_return}}% per year on unreturned capital, if stated.\n4. Split the remaining profit: Capital partner {{split_capital}}%, Operating partner {{split_operator}}%."),
        S("Timeline and exit", "Target timeline: {{timeline}}. If the Property has not been sold or refinanced by {{exit_trigger}}, Capital partner may require that it be listed for sale with a licensed broker at a price recommended by the broker, or may buy out Operating partner's interest at the value established by an independent appraisal, minus selling costs."),
        S("Operating partner's promises", "Operating partner will act in good faith, put the venture's interest first, disclose any relationship with contractors or buyers, and not take any undisclosed fee, kickback or markup. If a partner is a licensed real estate agent and will earn a commission, it must be disclosed and approved in writing."),
        S("Insurance and liability", "The venture will carry builder's risk or vacant-property insurance and liability insurance, with both partners or the venture as named insureds. Each partner indemnifies the other for losses caused by its own negligence, fraud or breach."),
        S("Default and removal", "If Operating partner abandons the project or materially breaches this agreement and does not cure within 15 days after notice, Capital partner may take over management, hire a replacement, and deduct the cost from Operating partner's share of profits."),
        S("Securities and taxes", "The partners intend for both to participate actively in major decisions. They have been advised that if one partner is a passive investor, securities laws may apply. The venture will file any required tax returns. Each partner pays its own income taxes."),
        S("Disputes", "The partners will negotiate in good faith, then mediate, before litigation."),
        general_terms(),
        signatures([("capital", "Capital partner", "{{capital_name}}", True), ("operator", "Operating partner", "{{operator_name}}", True)]),
    ],
    sources=[SRC["sec_jv"], SRC["irs_partnership"], src("SEC v. W.J. Howey Co., 328 U.S. 293 (1946) (Justia)", "https://supreme.justia.com/cases/federal/us/328/293/"), SRC["esign"]],
))
